/**
 * I29: External Parity Suite — CA vs causal-learn.
 *
 * Runs Causality Analyzer algorithms on the same benchmark data
 * used by the causal-learn bridge (scripts/causal-learn-bridge.py).
 * Compares SHD metrics to validate CA's algorithm precision
 * against the Python gold standard.
 *
 * The causal-learn reference data is generated by:
 *   python3 scripts/causal-learn-bridge.py > parity-ref.json
 */
import { describe, it, expect } from 'vitest';
import { Matrix } from 'ml-matrix';
import { pcAlgorithm } from '../../src/graph/pc.js';
import { gesAlgorithm } from '../../src/graph/ges.js';
import { fciAlgorithm } from '../../src/graph/advanced-discovery.js';
import { bossAlgorithm } from '../../src/graph/boss.js';
import { gfciAlgorithm } from '../../src/graph/gfci.js';
import { generateLinearData, computeSHD, asiaGraph, butterflyGraph, mBiasGraph, randomDAG } from '../../src/benchmark.js';
import type { CausalGraph } from '../../src/graph/causal-graph.js';

/** cached causal-learn reference data from bridge */
let _clRef: Record<string, Array<{ algorithm: string; shd: number; tpr: number; fpr: number }>> | null = null;

function getCLRef(): typeof _clRef {
  if (_clRef) return _clRef;
  // Embedded reference results from causal-learn 0.1.4.8
  // Generated: python3 scripts/causal-learn-bridge.py
  // These are the known-good reference values
  _clRef = {
    'ASIA': [
      { algorithm: 'cl-PC', shd: 5, tpr: 0.625, fpr: 0.286 },
      { algorithm: 'cl-GES', shd: 3, tpr: 0.625, fpr: 0.0 },
      { algorithm: 'cl-FCI', shd: 6, tpr: 0.25, fpr: 0.0 },
    ],
    'Butterfly': [
      { algorithm: 'cl-PC', shd: 4, tpr: 0.0, fpr: 0.0 },
      { algorithm: 'cl-GES', shd: 4, tpr: 0.0, fpr: 0.0 },
      { algorithm: 'cl-FCI', shd: 4, tpr: 0.0, fpr: 0.0 },
    ],
    'M-Bias': [
      { algorithm: 'cl-PC', shd: 2, tpr: 0.5, fpr: 0.0 },
      { algorithm: 'cl-GES', shd: 2, tpr: 0.5, fpr: 0.0 },
      { algorithm: 'cl-FCI', shd: 4, tpr: 0.0, fpr: 0.0 },
    ],
    'Random-5': [
      { algorithm: 'cl-PC', shd: 4, tpr: 0.0, fpr: 0.0 },
      { algorithm: 'cl-GES', shd: 4, tpr: 0.0, fpr: 0.0 },
      { algorithm: 'cl-FCI', shd: 4, tpr: 0.0, fpr: 0.0 },
    ],
  };
  return _clRef;
}

type AlgoName = string;
type AlgoFn = (data: number[][], nodes: string[], truth: CausalGraph) => { name: string; graph: CausalGraph };

const CA_ALGOS: Array<{ name: string; fn: (data: number[][], nodes: string[]) => CausalGraph; clName: string }> = [
  { name: 'ca-PC', fn: (d, n) => pcAlgorithm(new Matrix(d), n).graph, clName: 'cl-PC' },
  { name: 'ca-GES', fn: (d, n) => gesAlgorithm(new Matrix(d), n), clName: 'cl-GES' },
  { name: 'ca-FCI', fn: (d, n) => fciAlgorithm(new Matrix(d), n).graph, clName: 'cl-FCI' },
];

const BENCHMARKS = [
  { name: 'ASIA', gen: () => ({ graph: asiaGraph(), n: 500 }) },
  { name: 'Butterfly', gen: () => ({ graph: butterflyGraph(), n: 300 }) },
  { name: 'M-Bias', gen: () => ({ graph: mBiasGraph(), n: 300 }) },
  { name: 'Random-5', gen: () => ({ graph: randomDAG(5, 0.25, 42), n: 300 }) },
];

describe('Causal-Learn External Parity', () => {
  const clRef = getCLRef()!;

  for (const { name, gen } of BENCHMARKS) {
    const { graph: truth, n } = gen();
    const { data, nodeNames } = generateLinearData(truth, n, 42);

    describe(`${name} (${truth.nodes.length} nodes)`, () => {
      for (const algo of CA_ALGOS) {
        it(`${algo.name} regression check vs causal-learn ${algo.clName}`, () => {
          const predicted = algo.fn(data, nodeNames);
          const metrics = computeSHD(predicted, truth);

          const clResult = clRef[name]!.find(r => r.algorithm === algo.clName);
          if (!clResult || clResult.shd < 0) return;

          // CPDAG-space GES (I32) narrows gap vs causal-learn significantly
          expect(metrics.shd).toBeLessThanOrEqual(Math.max(clResult.shd + 4, 12));
          expect(isFinite(metrics.shd)).toBe(true);
          expect(metrics.shd).toBeGreaterThanOrEqual(0);
        });
      }

      it('ca-BOSS produces valid DAG and has SHD in reasonable range', () => {
        if (truth.nodes.length > 5) return; // BOSS is slow on larger graphs
        const predicted = bossAlgorithm(new Matrix(data), nodeNames, { numStarts: 2, maxIter: 15 });
        const metrics = computeSHD(predicted, truth);
        expect(predicted.isDAG()).toBe(true);
        // BOSS should perform at least as well as GES on average
        const gesGraph = gesAlgorithm(new Matrix(data), nodeNames);
        const gesMetrics = computeSHD(gesGraph, truth);
        expect(metrics.shd).toBeLessThanOrEqual(gesMetrics.shd + 3);
      });

      it('ca-GFCI produces valid graph without crash', () => {
        if (truth.nodes.length > 5) return;
        const result = gfciAlgorithm(new Matrix(data), nodeNames);
        expect(result.graph.nodes.length).toBe(truth.nodes.length);
        expect(result.pagEdges.size).toBeGreaterThan(0);
      });
    });
  }
});
